USE DATABASE MM_REFERENCE;

-- Idempotent dedupe by business key; latest ingest timestamp wins with stable source-file tie breaker.

-- Existing Silver records are overwritten on matching keys.

MERGE INTO SILVER.CUSTOMER t USING (SELECT CUSTOMER_ID, FIRST_NAME, LAST_NAME, UPPER(TRIM(STATE)) AS STATE, BIRTH_DATE FROM BRONZE.CUSTOMER
 QUALIFY ROW_NUMBER() OVER (PARTITION BY CUSTOMER_ID ORDER BY INGESTED_AT DESC, SOURCE_FILE DESC)=1) s
 ON t.CUSTOMER_ID=s.CUSTOMER_ID
 WHEN MATCHED THEN UPDATE SET t.FIRST_NAME=s.FIRST_NAME, t.LAST_NAME=s.LAST_NAME, t.STATE=s.STATE, t.BIRTH_DATE=s.BIRTH_DATE, t.UPDATED_AT_PIPELINE=CURRENT_TIMESTAMP()
 WHEN NOT MATCHED THEN INSERT (CUSTOMER_ID, FIRST_NAME, LAST_NAME, STATE, BIRTH_DATE, UPDATED_AT_PIPELINE) VALUES (s.CUSTOMER_ID, s.FIRST_NAME, s.LAST_NAME, s.STATE, s.BIRTH_DATE, CURRENT_TIMESTAMP());

MERGE INTO SILVER.INSURANCE_PRODUCT t USING (SELECT PRODUCT_ID, PRODUCT_NAME, UPPER(TRIM(LINE_OF_BUSINESS)) AS LINE_OF_BUSINESS FROM BRONZE.INSURANCE_PRODUCT
 QUALIFY ROW_NUMBER() OVER (PARTITION BY PRODUCT_ID ORDER BY INGESTED_AT DESC, SOURCE_FILE DESC)=1) s
 ON t.PRODUCT_ID=s.PRODUCT_ID
 WHEN MATCHED THEN UPDATE SET t.PRODUCT_NAME=s.PRODUCT_NAME, t.LINE_OF_BUSINESS=s.LINE_OF_BUSINESS, t.UPDATED_AT_PIPELINE=CURRENT_TIMESTAMP()
 WHEN NOT MATCHED THEN INSERT (PRODUCT_ID, PRODUCT_NAME, LINE_OF_BUSINESS, UPDATED_AT_PIPELINE) VALUES (s.PRODUCT_ID, s.PRODUCT_NAME, s.LINE_OF_BUSINESS, CURRENT_TIMESTAMP());

MERGE INTO SILVER.POLICY t USING (SELECT POLICY_ID, CUSTOMER_ID, PRODUCT_ID, UPPER(TRIM(POLICY_STATUS)) AS POLICY_STATUS, EFFECTIVE_DATE, ANNUAL_PREMIUM, UPDATED_AT FROM BRONZE.POLICY
 QUALIFY ROW_NUMBER() OVER (PARTITION BY POLICY_ID ORDER BY INGESTED_AT DESC, SOURCE_FILE DESC)=1) s
 ON t.POLICY_ID=s.POLICY_ID
 WHEN MATCHED THEN UPDATE SET t.CUSTOMER_ID=s.CUSTOMER_ID, t.PRODUCT_ID=s.PRODUCT_ID, t.POLICY_STATUS=s.POLICY_STATUS, t.EFFECTIVE_DATE=s.EFFECTIVE_DATE, t.ANNUAL_PREMIUM=s.ANNUAL_PREMIUM, t.UPDATED_AT=s.UPDATED_AT, t.UPDATED_AT_PIPELINE=CURRENT_TIMESTAMP()
 WHEN NOT MATCHED THEN INSERT (POLICY_ID, CUSTOMER_ID, PRODUCT_ID, POLICY_STATUS, EFFECTIVE_DATE, ANNUAL_PREMIUM, UPDATED_AT, UPDATED_AT_PIPELINE) VALUES (s.POLICY_ID, s.CUSTOMER_ID, s.PRODUCT_ID, s.POLICY_STATUS, s.EFFECTIVE_DATE, s.ANNUAL_PREMIUM, s.UPDATED_AT, CURRENT_TIMESTAMP());

MERGE INTO SILVER.COVERAGE t USING (SELECT COVERAGE_ID, POLICY_ID, COVERAGE_TYPE, FACE_AMOUNT FROM BRONZE.COVERAGE
 QUALIFY ROW_NUMBER() OVER (PARTITION BY COVERAGE_ID ORDER BY INGESTED_AT DESC, SOURCE_FILE DESC)=1) s
 ON t.COVERAGE_ID=s.COVERAGE_ID
 WHEN MATCHED THEN UPDATE SET t.POLICY_ID=s.POLICY_ID, t.COVERAGE_TYPE=s.COVERAGE_TYPE, t.FACE_AMOUNT=s.FACE_AMOUNT, t.UPDATED_AT_PIPELINE=CURRENT_TIMESTAMP()
 WHEN NOT MATCHED THEN INSERT (COVERAGE_ID, POLICY_ID, COVERAGE_TYPE, FACE_AMOUNT, UPDATED_AT_PIPELINE) VALUES (s.COVERAGE_ID, s.POLICY_ID, s.COVERAGE_TYPE, s.FACE_AMOUNT, CURRENT_TIMESTAMP());

MERGE INTO SILVER.ADVISOR t USING (SELECT ADVISOR_ID, ADVISOR_NAME, REGION FROM BRONZE.ADVISOR
 QUALIFY ROW_NUMBER() OVER (PARTITION BY ADVISOR_ID ORDER BY INGESTED_AT DESC, SOURCE_FILE DESC)=1) s
 ON t.ADVISOR_ID=s.ADVISOR_ID
 WHEN MATCHED THEN UPDATE SET t.ADVISOR_NAME=s.ADVISOR_NAME, t.REGION=s.REGION, t.UPDATED_AT_PIPELINE=CURRENT_TIMESTAMP()
 WHEN NOT MATCHED THEN INSERT (ADVISOR_ID, ADVISOR_NAME, REGION, UPDATED_AT_PIPELINE) VALUES (s.ADVISOR_ID, s.ADVISOR_NAME, s.REGION, CURRENT_TIMESTAMP());

MERGE INTO SILVER.WEALTH_ACCOUNT t USING (SELECT ACCOUNT_ID, CUSTOMER_ID, ADVISOR_ID, ACCOUNT_TYPE, OPENED_DATE, UPPER(TRIM(ACCOUNT_STATUS)) AS ACCOUNT_STATUS FROM BRONZE.WEALTH_ACCOUNT
 QUALIFY ROW_NUMBER() OVER (PARTITION BY ACCOUNT_ID ORDER BY INGESTED_AT DESC, SOURCE_FILE DESC)=1) s
 ON t.ACCOUNT_ID=s.ACCOUNT_ID
 WHEN MATCHED THEN UPDATE SET t.CUSTOMER_ID=s.CUSTOMER_ID, t.ADVISOR_ID=s.ADVISOR_ID, t.ACCOUNT_TYPE=s.ACCOUNT_TYPE, t.OPENED_DATE=s.OPENED_DATE, t.ACCOUNT_STATUS=s.ACCOUNT_STATUS, t.UPDATED_AT_PIPELINE=CURRENT_TIMESTAMP()
 WHEN NOT MATCHED THEN INSERT (ACCOUNT_ID, CUSTOMER_ID, ADVISOR_ID, ACCOUNT_TYPE, OPENED_DATE, ACCOUNT_STATUS, UPDATED_AT_PIPELINE) VALUES (s.ACCOUNT_ID, s.CUSTOMER_ID, s.ADVISOR_ID, s.ACCOUNT_TYPE, s.OPENED_DATE, s.ACCOUNT_STATUS, CURRENT_TIMESTAMP());

MERGE INTO SILVER.HOLDING t USING (SELECT HOLDING_ID, ACCOUNT_ID, SECURITY_SYMBOL, QUANTITY, MARKET_PRICE, AS_OF_DATE FROM BRONZE.HOLDING
 QUALIFY ROW_NUMBER() OVER (PARTITION BY HOLDING_ID ORDER BY INGESTED_AT DESC, SOURCE_FILE DESC)=1) s
