 WHEN MATCHED THEN UPDATE SET t.ACCOUNT_ID=s.ACCOUNT_ID, t.SECURITY_SYMBOL=s.SECURITY_SYMBOL, t.QUANTITY=s.QUANTITY, t.MARKET_PRICE=s.MARKET_PRICE, t.AS_OF_DATE=s.AS_OF_DATE, t.UPDATED_AT_PIPELINE=CURRENT_TIMESTAMP()
 WHEN NOT MATCHED THEN INSERT (HOLDING_ID, ACCOUNT_ID, SECURITY_SYMBOL, QUANTITY, MARKET_PRICE, AS_OF_DATE, UPDATED_AT_PIPELINE) VALUES (s.HOLDING_ID, s.ACCOUNT_ID, s.SECURITY_SYMBOL, s.QUANTITY, s.MARKET_PRICE, s.AS_OF_DATE, CURRENT_TIMESTAMP());

MERGE INTO SILVER.TRANSACTION t USING (SELECT TRANSACTION_ID, ACCOUNT_ID, TRANSACTION_DATE, UPPER(TRIM(TRANSACTION_TYPE)) AS TRANSACTION_TYPE, AMOUNT FROM BRONZE.TRANSACTION
 QUALIFY ROW_NUMBER() OVER (PARTITION BY TRANSACTION_ID ORDER BY INGESTED_AT DESC, SOURCE_FILE DESC)=1) s
 ON t.TRANSACTION_ID=s.TRANSACTION_ID
 WHEN MATCHED THEN UPDATE SET t.ACCOUNT_ID=s.ACCOUNT_ID, t.TRANSACTION_DATE=s.TRANSACTION_DATE, t.TRANSACTION_TYPE=s.TRANSACTION_TYPE, t.AMOUNT=s.AMOUNT, t.UPDATED_AT_PIPELINE=CURRENT_TIMESTAMP()
 WHEN NOT MATCHED THEN INSERT (TRANSACTION_ID, ACCOUNT_ID, TRANSACTION_DATE, TRANSACTION_TYPE, AMOUNT, UPDATED_AT_PIPELINE) VALUES (s.TRANSACTION_ID, s.ACCOUNT_ID, s.TRANSACTION_DATE, s.TRANSACTION_TYPE, s.AMOUNT, CURRENT_TIMESTAMP());